  'agentBrief.copy': 'Copy for AI agent',
  'agentBrief.copyHint': 'Copies a Markdown brief with context, findings, evidence and steps, ready to paste into Claude Code, Codex, ChatGPT or another agent',
  'agentBrief.download': 'Download brief (.md)',
  'agentBrief.copied': 'Brief copied: paste it into your AI agent',
