  'agentBrief.generatedBy': 'Generated by KUA (Know Unified Administration) on {date}, from deterministic checks on data KUA already reads. No AI was involved and no values were guessed.',
  'agentBrief.advisorTitle': 'KUA brief: good-practice findings',
  'agentBrief.advisorTitleProduct': 'KUA brief: product findings',
  'agentBrief.logsTitle': 'KUA brief: log intelligence for {group}',
  'agentBrief.context': 'Context',
  'agentBrief.task': 'Your task',
  'agentBrief.taskIntro': 'You are an engineer with access to the code, infrastructure as code and cloud CLI of this workload. Resolve the findings below following these rules:',
  'agentBrief.rule.verify': 'Verify each finding against the current state (CLI, console or repository) before changing anything: this brief is a snapshot and may be outdated.',
  'agentBrief.rule.order': 'Work by severity (high first). Group findings that share a root cause and fix the cause, not each symptom.',
  'agentBrief.rule.iac': 'If the resources are managed by infrastructure as code (Terraform, CloudFormation, CDK, Helm, Kubernetes manifests), change the code and propose a reviewable diff instead of changing the cloud by hand.',
  'agentBrief.rule.confirm': 'Do not run destructive or billed operations (delete, replace, restart in production, scale up) without explicit confirmation. Say what each step costs when it has a cost.',
  'agentBrief.rule.secrets': 'Never print, log or commit secrets. Sensitive values were already redacted by KUA: do not try to recover them.',
  'agentBrief.rule.report': 'Finish with a short report: what you changed, what you left out and why, and how it was verified.',
  'agentBrief.rule.logsLocate': 'Locate the code that writes these logs (search the repository for the signatures and samples) before proposing a fix.',
  'agentBrief.findings': 'Findings ({n})',
