  'agentBrief.verify': 'How to verify',
  'agentBrief.verifyAdvisor': 'After the changes, run the Advisor again in KUA ("Scan again" in the overview): the fixed findings must disappear. Also confirm with the provider CLI that each resource has the expected configuration.',
  'agentBrief.verifyProduct': 'After the changes, update the application in KUApps and scan again: the fixed findings must disappear.',
  'agentBrief.verifyLogs': 'After deploying, watch the log group in KUA Intelligence: the error rate and the occurrences of the signatures above must drop in the next 24 h. Use the queries above in CloudWatch Logs Insights to confirm.',
