  'agentConnect.open': 'Connect AI agents (MCP)',
  'agentConnect.title': 'Connect AI agents to KUA',
  'agentConnect.intro': 'The KUA MCP server lets Claude Code, Codex and other agents read these findings and the log intelligence directly, without copying briefs. Install it in your agent with one click, or paste this setup once; the paths already point to this installation.',
  'agentConnect.client.claude': 'Claude Code',
  'agentConnect.client.codex': 'Codex CLI',
  'agentConnect.client.json': 'JSON (.mcp.json, Cursor, VS Code)',
  'agentConnect.client.toml': 'Codex config.toml',
  'agentConnect.hint.claude': 'Install it with the button, or run the command in a terminal; then check it with /mcp inside Claude Code.',
  'agentConnect.hint.codex': 'Install it with the button, or run the command in a terminal; then check it with /mcp inside Codex.',
  'agentConnect.hint.json': 'Add it to .mcp.json at the root of a project (Claude Code) or to the MCP settings of Cursor, VS Code or Windsurf.',
  'agentConnect.hint.toml': 'Add it to ~/.codex/config.toml.',
  'agentConnect.copy': 'Copy',
  'agentConnect.copied': 'Setup copied',
  'agentConnect.noteOpen': 'KUA must be open while the agent uses it. The server finds it by itself, on any port (installed app or development); set KUA_URL only to point it somewhere else.',
  'agentConnect.notePackaged': 'It runs with the KuaDashboard executable, so Node.js is not needed. After moving or reinstalling KUA, copy the setup again.',
  'agentConnect.noteReadOnly': 'Every tool is read-only: no billed calls, and credentials never leave KUA.',
  'agentConnect.noteChatgpt': 'ChatGPT web and desktop only accept remote MCP servers over HTTPS; use "Copy for AI agent" there.',
